// 장비 데이터. 이 파일만 고치면 사이트 내용이 바뀐다.
// 이미지는 위키(Military Tycoon Fandom) 주소를 그대로 쓴다.
//
// 필드 설명
//   id         고유 영문 ID (주소·비교에 쓰임)
//   name       표시 이름
//   category   "Land" | "Air" | "Naval" | "Soldier" | "Drone" | "Tags" | "Other"
//   value      거래 가치 (숫자, 단위 Gems 💎)
//   demand     수요 0~10
//   trend      "up" | "down" | "stable"
//   tradeable  거래 가능 여부
//   limited    한정판(LE) 여부, stock: 한정 수량 (모르면 null)
//   rarity     등급 (선택). "Exotic"이면 무지개 태그
//   value      가치 (강화 무시). range: [최소, 최대] 또는 [최소, "+"] 로 범위 표시 (value는 최소값. 정렬·거래 계산·그래프는 최대값)
//   fresh      강화 안 한(0성) 가치가 다를 때만 적는다
//   stats      성능 { pvp, vfm, diff } 0~10 (PVP, 가성비, 난이도=다루기 어려운 정도, 소수 가능). 모르면 null
//   obtain     얻는 방법
//   updated    값을 마지막으로 바꾼 날 "YYYY-MM-DD"
//   starHistory 별 단계 기록 (선택) { "fresh": [{date, value}], "1": [...], "2": [...], "3": [...] }. history는 0성
//   history    젬 가치 변화 [{ date, value }]. 가치를 바꿀 때마다 끝에 추가. date는 "YYYY-MM" 또는 같은 달 안 변화는 "YYYY-MM-DD"
//   trend      "up" | "down" | "stable" | "unstable" | "hyped"
//   image      게임 아이콘 경로 images/<id>.png (없으면 빈 문자열)
//   video      쇼케이스 유튜브 영상 ID (선택, @lionhe4rted 채널)
//   note       메모 (영어), noteKo: 한국어 메모
//   aliases    검색용 다른 이름 (예: ["Abrams", "에이브럼스"])

